// Gyroid Cathedral: a flight through an endless gyroid, the minimal surface
// that splits space into two interlocking labyrinths. A corridor is carved
// along the camera path so the flight never hits a wall. The walls are an
// oil-film: their colour depends on the viewing angle, so everything shifts
// as the camera moves. Light pulses run through veins in the walls and
// surge forward with every beat.
//
// Everything is measured from the camera's depth and the flight is counted
// in lattice phase, so the numbers stay small all night and changing the
// lattice rescales space around the viewer instead of a far-away origin.

#define TAU 6.28318531

float S;  // lattice frequency
float TH; // wall thickness
float TW; // twist of space per unit of depth
float U;  // distance flown, in lattice phase

mat2 rot(float a) {
  float c = cos(a);
  float s = sin(a);
  return mat2(c, -s, s, c);
}

vec3 palette(float t) {
  return 0.5 + 0.5 * cos(TAU * (t + vec3(0.0, 0.33, 0.67)));
}

vec2 path(float u) {
  return vec2(sin(u * 0.08) * 0.5 + sin(u * 0.033) * 0.3, cos(u * 0.06) * 0.5);
}

// x: the gyroid, y: a finer gyroid riding on it (surface relief and veins).
vec2 field(vec3 p) {
  p.xy = rot(p.z * TW) * p.xy;
  vec3 q = p * S;
  q.z += mod(U, TAU);
  float g = dot(sin(q), cos(q.yzx));
  float f = dot(sin(q * 3.0 + g), cos(q.zxy * 3.0));
  return vec2(g, f);
}

float map(vec3 p) {
  vec2 f = field(p);
  float d = (abs(f.x) - TH) / S - f.y * 0.012;
  // Smooth-subtract the corridor around the camera path.
  float tube = 0.42 - length(p.xy - path(U + p.z * S));
  float k = 0.3;
  float h = clamp(0.5 + 0.5 * (tube - d) / k, 0.0, 1.0);
  return mix(d, tube, h) + k * h * (1.0 - h);
}

vec3 normalAt(vec3 p, float eps) {
  vec2 e = vec2(1.0, -1.0) * eps;
  return normalize(
    e.xyy * map(p + e.xyy) + e.yyx * map(p + e.yyx) +
    e.yxy * map(p + e.yxy) + e.xxx * map(p + e.xxx)
  );
}

vec3 shader(vec2 uv, float time) {
  float j = drift + kick;
  vec2 p = (uv - 0.5) * vec2(resolution.x / resolution.y, 1.0) * 2.0;

  S = mix(2.0, 6.0, weave);
  TH = mix(0.04, 1.1, shell) * (1.0 + 0.12 * sin(j * 0.11));
  TW = twist * 0.6;
  float hue = colour + j * 0.011;

  U = j * 3.0;
  vec3 ro = vec3(path(U), 0.0);
  vec3 fw = normalize(vec3(path(U + S), 1.0) - ro);
  vec3 rt = normalize(cross(vec3(0.0, 1.0, 0.0), fw));
  vec3 up = cross(fw, rt);
  p = rot(0.7 * sin(j * 0.05)) * p;
  vec3 rd = normalize(fw + (p.x * rt + p.y * up) * 0.9);

  float t = 0.05;
  float haze = 0.0;
  float hit = 0.0;
  for (int i = 0; i < 72; i++) {
    float d = map(ro + rd * t);
    haze += exp(-10.0 * abs(d));
    if (d < 0.0012 * t + 0.0004) {
      hit = 1.0;
      break;
    }
    t += d * 0.6;
    if (t > 12.0) break;
  }

  vec3 fogCol = palette(hue + 0.55 + 0.12 * rd.y) * 0.07;
  vec3 col = fogCol;
  if (hit > 0.5) {
    vec3 pos = ro + rd * t;
    vec3 n = normalAt(pos, 0.002 + 0.0015 * t);
    vec2 f = field(pos);
    float facing = max(dot(n, -rd), 0.0);

    // Oil film: hue follows the viewing angle and the relief.
    float film = facing * 0.9 + f.y * 0.2 + pos.z * 0.06;
    vec3 base = palette(hue + film);

    // A lamp travelling just ahead of the camera.
    vec3 ld = ro + fw * 1.5 - pos;
    float ll = length(ld);
    ld /= ll;
    float fall = 1.0 / (1.0 + 0.12 * ll * ll);
    float dif = max(dot(n, ld), 0.0) * fall;
    float spec = pow(max(dot(reflect(rd, n), ld), 0.0), 20.0) * fall;

    // ... and a weaker one on the camera itself, for the walls beside it.
    float head = facing / (1.0 + 0.15 * t * t);

    col = base * (0.1 + 1.5 * dif + 0.5 * head) + spec * 0.7;
    col += palette(hue + film + 0.3) * pow(1.0 - facing, 3.0) * 0.7;

    // Veins along the zero lines of the fine field carry pulses of light.
    float vein = smoothstep(0.14 + 0.04 * t, 0.0, abs(f.y));
    float wave = pow(0.5 + 0.5 * sin(pos.z * 1.3 - j * 2.5), 6.0);
    col += palette(hue + 0.5 + pos.z * 0.04) * vein * (0.45 + 2.0 * wave) * glow;

    col = mix(fogCol, col, exp(-0.018 * t * t));
  }
  col += palette(hue + 0.25) * haze * 0.012 * glow;

  col *= 1.0 - 0.3 * smoothstep(0.5, 1.6, length(p));
  return clamp(col, 0.0, 1.0);
}
